import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
import Testing
@testable import InfluxKit

/// The rich feed contract files (Fixtures/SammyRichContract, generated by
/// the server and copied verbatim), and what the rest of the rich feed
/// tests share.
enum RichFixtures {
    static let origin = "https://example.com"
    static let subject = "AbCdEfGhIjKlMnOpQrStUv"
    static let accountID = "\(subject)@example.com"
    static let richFeedID = "0193a1b2-0000-7000-8000-00000000f003"
    static let richFeedURL = "\(origin)/api/v1/feeds/\(richFeedID)"
    static let secondPageURL = "\(richFeedURL)?before=contract-page-2"
    static let articleFeedID = "0193a1b2-0000-7000-8000-00000000f005"
    static let articleFeedURL = "\(origin)/api/v1/feeds/\(articleFeedID)"
    /// What an article page and the article list are served as.
    static let articlePageHeaders = ["Content-Type": "application/feed+json; charset=utf-8"]
    static let articleListHeaders = ["Content-Type": "application/json"]
    /// A time within a week of every post in the pages.
    static let now = FeedDate.iso8601("2026-11-05T00:00:00Z")!

    static func data(_ name: String, in folder: String = "Fixtures/SammyRichContract") throws -> Data {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: nil, subdirectory: folder))
        return try Data(contentsOf: url)
    }

    static func object(_ name: String) throws -> [String: Any] {
        try #require(try JSONSerialization.jsonObject(with: data(name)) as? [String: Any])
    }

    /// The headers the server recorded for a 200 of `kind`, "page" or
    /// "list".
    static func headers(_ kind: String) throws -> [String: String] {
        let responses = try #require(object("rich-feed-negotiation.json")["responses"] as? [String: Any])
        let response = try #require(responses[kind] as? [String: Any])
        return try #require(response["headers"] as? [String: String])
    }

    /// `name`, a page, with `change` made to its JSON: for cases the
    /// server never sends. The files themselves are never changed.
    static func page(_ name: String, _ change: (inout [String: Any]) throws -> Void) throws -> Data {
        var object = try object(name)
        try change(&object)
        return try JSONSerialization.data(withJSONObject: object)
    }

    /// The items of page 1 as objects, to make changed copies of.
    static func pageOneItems() throws -> [[String: Any]] {
        try #require(object("rich-feed-page-1.json")["items"] as? [[String: Any]])
    }

    static func session() -> SammySession {
        SammySession(issuer: URL(string: origin)!, revocationEndpoint: URL(string: "\(origin)/oauth/revoke"),
                     accessToken: "sao_contract-example-access-token", subject: subject)
    }

    /// The rich feed's source, as the list makes it, with `itemKind`.
    static func source(_ itemKind: Item.Kind?, feedID: String = richFeedID) -> Source {
        Source(id: SammyFeedConnector.sourceID(accountID: accountID, feedID: feedID), kind: .sammyFeed, accountID: accountID,
               title: "Authored posts", url: "\(origin)/api/v1/feeds/\(feedID)", colorIndex: 0, itemKind: itemKind)
    }

    static func connector(_ http: FakeHTTPClient) throws -> SammyFeedConnector {
        let credentials = InMemoryCredentialStore()
        let session = session()
        try credentials.save(session, for: session.accountID)
        let account = SammyAccount(session: session, http: http, credentials: credentials)
        return SammyFeedConnector(account: account, http: http, resolver: .testing(http))
    }

    /// A server with both rich pages, served with the recorded headers.
    static func pages() throws -> FakeHTTPClient {
        let headers = try headers("page")
        let first = try data("rich-feed-page-1.json"), second = try data("rich-feed-page-2.json")
        return FakeHTTPClient { request in
            switch request.url?.absoluteString {
            case richFeedURL: .init(headers: headers, body: first)
            case secondPageURL: .init(headers: headers, body: second)
            default: .init(status: 404)
            }
        }
    }

    /// Serves `body` with `headers` for every request.
    static func answering(_ body: Data, headers: [String: String], status: Int = 200) -> FakeHTTPClient {
        FakeHTTPClient { _ in .init(status: status, headers: headers, body: body) }
    }

    static func request(_ source: Source, _ direction: FetchDirection = .newer, cursor: Cursor? = nil, stored: Set<String> = [],
                        now: Date = now) -> FetchRequest {
        var request = Refresher.request(for: source, direction: direction, cursor: cursor, now: now)
        request.storedRemoteIDs = stored
        return request
    }

    static func response(_ headers: [String: String], status: Int = 200) -> HTTPURLResponse {
        HTTPURLResponse(url: URL(string: richFeedURL)!, statusCode: status, httpVersion: "HTTP/1.1", headerFields: headers)!
    }
}

@Suite struct SammyRichContractTests {
    private typealias Files = RichFixtures

    // MARK: The files

    @Test func everyFileMatchesItsHashInTheManifest() throws {
        struct Manifest: Decodable {
            struct File: Decodable { var name: String; var sha256: String }
            var contractVersion: Int
            var files: [File]
        }
        let manifest = try JSONDecoder().decode(Manifest.self, from: Files.data("manifest.json"))
        #expect(manifest.contractVersion == 8)
        #expect(manifest.files.count == 19)
        for file in manifest.files {
            #expect(TestSHA256.hex(try Files.data(file.name)) == file.sha256, "\(file.name)")
        }
        // Every file in the folder is in the manifest: none added by hand.
        let folder = try #require(Bundle.module.url(forResource: "manifest", withExtension: "json", subdirectory: "Fixtures/SammyRichContract"))
            .deletingLastPathComponent()
        let present = try FileManager.default.contentsOfDirectory(atPath: folder.path).filter { $0 != "manifest.json" && $0 != "README.md" }
        #expect(Set(present) == Set(manifest.files.map(\.name)))
    }

    // MARK: Negotiation

    @Test func bothAcceptValuesThisBuildSendsAreAnsweredAsItReliesOn() throws {
        #expect(SammyNegotiation.rich == "application/vnd.sammy.rich-feed+json; version=1")
        #expect(SammyNegotiation.either == "application/vnd.sammy.rich-feed+json; version=1, application/feed+json")
        let cases = try #require(Files.object("rich-feed-negotiation.json")["cases"] as? [[String: Any]])
        func answers(_ accept: String) throws -> [String: String] {
            let found = try #require(cases.first { $0["accept"] as? String == accept }, "\(accept)")
            return ["list": found["list"] as? String ?? "", "articleFeed": found["articleFeed"] as? String ?? "",
                    "richFeed": found["richFeed"] as? String ?? ""]
        }
        // Rich alone, for a feed listed as posts: an article feed refuses it.
        #expect(try answers(SammyNegotiation.rich) == ["list": "rich", "articleFeed": "not-acceptable", "richFeed": "rich"])
        // Either, for the list and every other feed: each answers as it is.
        #expect(try answers(SammyNegotiation.either) == ["list": "rich", "articleFeed": "article", "richFeed": "rich"])
        // A build that asks only for articles is refused by a rich feed.
        #expect(try answers("application/feed+json")["richFeed"] == "not-acceptable")
    }

    @Test func requestsAskForWhatTheSourceIsKnownToHold() {
        let url = URL(string: Files.richFeedURL)!
        #expect(SammyFeedList.request(issuer: URL(string: Files.origin)!).value(forHTTPHeaderField: "Accept") == SammyNegotiation.either)
        #expect(SammyNegotiation.accept(for: .post) == SammyNegotiation.rich)
        #expect(SammyNegotiation.accept(for: .article) == SammyNegotiation.either)
        #expect(SammyNegotiation.accept(for: nil) == SammyNegotiation.either)
        #expect(SammyFeedConnector.feedRequest(url, accept: SammyNegotiation.rich, etag: nil).value(forHTTPHeaderField: "Accept") == SammyNegotiation.rich)
    }

    @Test func theRecordedHeadersChooseTheRichMapperAndNothingElseDoes() throws {
        for kind in ["page", "list"] {
            #expect(SammyNegotiation.representation(of: Files.response(try Files.headers(kind))) == .rich)
        }
        let cases: [(String?, SammyNegotiation.Representation?)] = [
            ("application/vnd.sammy.rich-feed+json;version=1", .rich),
            ("Application/Vnd.Sammy.Rich-Feed+JSON; Version=1", .rich),
            ("application/feed+json", .article),
            ("application/feed+json; charset=utf-8", .article),
            ("application/json", .article),
            ("application/vnd.sammy.rich-feed+json; version=2", nil),
            ("application/vnd.sammy.rich-feed+json", nil),
            ("application/vnd.sammy.rich-feed+json; version=1; charset=utf-8", nil),
            ("application/vnd.sammy.rich-feed+json; version=1; version=1", nil),
            ("application/vnd.sammy.rich-feed+json; version=1;", nil),
            ("text/html", nil),
            (nil, nil),
        ]
        for (type, expected) in cases {
            let headers = type.map { ["Content-Type": $0] } ?? [:]
            #expect(SammyNegotiation.representation(of: Files.response(headers)) == expected, "\(type ?? "none")")
        }
    }

    @Test func aRichPageUnderAnyOtherContentTypeIsRefused() async throws {
        let page = try Files.data("rich-feed-page-1.json")
        let types: [[String: String]] = [
            Files.articlePageHeaders, ["Content-Type": "application/vnd.sammy.rich-feed+json; version=2"], [:],
        ]
        for headers in types {
            let http = Files.answering(page, headers: headers)
            await #expect(throws: ConnectorError.self) {
                try await Files.connector(http).fetch(Files.request(Files.source(nil)), from: Files.source(nil))
            }
        }
        // An article body served as rich is refused too.
        let article = try Files.data("feed-page-1.json", in: "Fixtures/SammyContract")
        let http = Files.answering(article, headers: try Files.headers("page"))
        await #expect(throws: ConnectorError.badResponse("not a rich feed page")) {
            try await Files.connector(http).fetch(Files.request(Files.source(nil)), from: Files.source(nil))
        }
    }

    // MARK: The list

    @Test func theRichListBecomesSourcesThatSayWhatTheyHold() throws {
        let issuer = URL(string: Files.origin)!
        let headers = try Files.headers("list")
        let oauth = try SammyFeedList.decode(Files.data("rich-feed-list-oauth.json"), Files.response(headers), now: Files.now)
        #expect(oauth.account.id == Files.subject)
        let plain = try SammyFeedList.decode(Files.data("rich-feed-list.json"), Files.response(headers), now: Files.now)
        #expect(plain.account.id == nil)
        for list in [oauth, plain] {
            let sources = SammyFeedConnector.sources(of: list, accountID: Files.accountID, issuer: issuer, colorIndex: 0)
            #expect(sources.map(\.id) == [
                "sammy:\(Files.accountID):feed:0193a1b2-0000-7000-8000-00000000f005",
                "sammy:\(Files.accountID):feed:0193a1b2-0000-7000-8000-00000000f006",
                "sammy:\(Files.accountID):feed:\(Files.richFeedID)",
            ])
            #expect(sources.map(\.itemKind) == [.article, .article, .post])
            #expect(sources.allSatisfy { $0.kind == .sammyFeed && $0.accountID == Files.accountID })
            #expect(sources.map(\.title) == ["Example article feed", "Example notes feed", "Authored posts"])
        }
    }

    @Test func aListEntryOfAnUnknownFormatIsLeftOutAndAnUnknownListRefused() throws {
        let headers = try Files.headers("list")
        let changed = try Files.page("rich-feed-list-oauth.json") { list in
            var feeds = try #require(list["feeds"] as? [[String: Any]])
            feeds[0]["format"] = "video"
            feeds[1]["classification"] = ["kind": "post", "retentionDays": 7]
            feeds[2]["version"] = 2
            list["feeds"] = feeds
        }
        #expect(try SammyFeedList.decode(changed, Files.response(headers), now: Files.now).feeds.isEmpty)
        // An article entry is defined unversioned: one that names a version
        // is a later format, left out like any other.
        var versionedID = ""
        let versionedArticle = try Files.page("rich-feed-list-oauth.json") { list in
            var feeds = try #require(list["feeds"] as? [[String: Any]])
            let index = try #require(feeds.firstIndex { $0["format"] as? String == "article" })
            versionedID = try #require(feeds[index]["id"] as? String)
            feeds[index]["version"] = 1
            list["feeds"] = feeds
        }
        let kept = try SammyFeedList.decode(versionedArticle, Files.response(headers), now: Files.now).feeds
        let all = try SammyFeedList.decode(Files.data("rich-feed-list-oauth.json"), Files.response(headers), now: Files.now).feeds
        #expect(kept.count == all.count - 1)
        #expect(!kept.contains { $0.id == versionedID })
        for (key, value) in [("version", 2 as Any), ("format", "sammy.rich-feed" as Any)] {
            let other = try Files.page("rich-feed-list-oauth.json") { $0[key] = value }
            #expect(throws: ConnectorError.self) { try SammyFeedList.decode(other, Files.response(headers), now: Files.now) }
        }
        // A rich list served as an article list is refused, and an article
        // list says nothing of what its feeds hold.
        #expect(throws: ConnectorError.self) {
            try SammyFeedList.decode(Files.data("rich-feed-list-oauth.json"), Files.response(Files.articleListHeaders), now: Files.now)
        }
        let legacy = try SammyFeedList.decode(Files.data("feed-list-oauth.json", in: "Fixtures/SammyContract"),
                                              Files.response(Files.articleListHeaders), now: Files.now)
        #expect(legacy.feeds.count == 2 && legacy.feeds.allSatisfy { $0.itemKind == nil })
    }

    // MARK: Pages

    @Test func pagesMapToPostsWithTheirFullTextAndIdentity() async throws {
        let http = try Files.pages()
        let source = Files.source(.post)
        let connector = try Files.connector(http)
        let first = try await connector.fetch(Files.request(source), from: source)
        let items = try Files.pageOneItems()
        let text = try #require(items[0]["text"] as? String)
        #expect(text.count > 400)

        #expect(first.items.count == 2)
        let post = first.items[0]
        #expect(post.kind == .post)
        #expect(post.viewer == nil && post.title == nil && post.media.isEmpty && post.authorAvatar == nil && post.linkCard == nil)
        #expect(post.sourceID == source.id)
        #expect(post.remoteID == "urn:uuid:70ad2d4e-b17f-8d6d-84e0-14a6d944d82b")
        #expect(post.mergeKey == "sammy-post:example.com:urn:uuid:0193a1b2-0000-7000-8000-000000000002")
        #expect(post.url == "https://www.example.com/author/posts/2")
        #expect(post.authorName == "Example Author")
        #expect(post.authorHandle == "example.com")
        #expect(post.publishedAt == FeedDate.iso8601("2026-11-02T09:30:00Z"))
        #expect(post.fetchedAt == Files.now)
        // The text exactly as sent, markup and line breaks kept, and the
        // links it doesn't hold after it, one to a line.
        #expect(post.body.hasPrefix(text))
        #expect(post.body.contains("A second paragraph, with a line break\nthat matters."))
        #expect(post.body.contains("<b>Not markup</b> & not escaped: plain text is plain text."))
        let one = "https://www.example.com/read/one", two = "https://www.example.com/read/two"
        #expect(post.body == "\(text)\n\n\(one)\n\(two)")
        let start = text.utf16.count + 2
        #expect(post.links == [
            Item.Link(start: start, length: one.utf16.count, url: one),
            Item.Link(start: start + one.utf16.count + 1, length: two.utf16.count, url: two),
        ])
        #expect(first.items[1].body == "A different post with the same original URL and the same publish time.")
        #expect(first.items[1].links.isEmpty)
        #expect(first.older == Cursor(rawValue: Files.secondPageURL))

        // Page 2's post carries an extension a reader ignores.
        let second = try await connector.fetch(Files.request(source, .older, cursor: first.older), from: source)
        #expect(second.items.map(\.remoteID) == ["urn:uuid:a679f989-2da4-87ce-b043-1ed7ae334a44"])
        #expect(second.items[0].authorHandle == "example.com")
        #expect(second.older == nil)
        // Every request named the rich format alone, with the token, on
        // the server.
        #expect(http.requests.allSatisfy {
            $0.value(forHTTPHeaderField: "Accept") == SammyNegotiation.rich
                && $0.value(forHTTPHeaderField: "Authorization") == "Bearer sao_contract-example-access-token"
                && $0.url?.host() == "example.com"
        })
    }

    @Test func linksInTheTextLinkWhereTheyAreInUTF16() {
        let text = "Read 🙂 www.example.com/a, then https://www.example.com/b and https://www.example.com/b again."
        let links = [
            RichFeedPage.Link(url: "https://www.example.com/a", text: "www.example.com/a"),
            RichFeedPage.Link(url: "https://www.example.com/b", text: nil),
            RichFeedPage.Link(url: "https://www.example.com/b", text: nil),
            RichFeedPage.Link(url: "https://www.example.com/c", text: "nowhere"),
        ]
        let (body, placed) = RichFeedMapper.textAndLinks(text, links)
        #expect(body == text + "\n\nhttps://www.example.com/c")
        let utf16 = Array(body.utf16)
        func run(_ link: Item.Link) -> String { String(decoding: utf16[link.start..<(link.start + link.length)], as: UTF16.self) }
        #expect(placed.map(run) == ["www.example.com/a", "https://www.example.com/b", "https://www.example.com/b", "https://www.example.com/c"])
        #expect(placed.map(\.url) == ["https://www.example.com/a", "https://www.example.com/b", "https://www.example.com/b", "https://www.example.com/c"])
        #expect(placed[1].start != placed[2].start)
    }

    @Test func theIdentityCasesMergeOnlyTheSamePost() async throws {
        let cases = try #require(Files.object("rich-feed-identity.json")["cases"] as? [[String: Any]])
        #expect(cases.count == 5)
        for entry in cases {
            let name = entry["name"] as? String ?? ""
            let objects = try #require(entry["items"] as? [[String: Any]])
            let store = try InfluxStore.inMemory()
            // Each representation comes from a feed of its own.
            var items: [Item] = []
            var identities: [String: [String]] = [:]
            for (index, object) in objects.enumerated() {
                let feedID = "feed-\(index)"
                let source = Files.source(.post, feedID: feedID)
                try await store.save(sources: [source])
                let body = try JSONSerialization.data(withJSONObject: [
                    "format": "sammy.rich-feed", "version": 1,
                    "feed": ["id": feedID, "title": "Feed", "feedUrl": "\(Files.origin)/api/v1/feeds/\(feedID)"],
                    "items": [object],
                ])
                let page = try RichFeedPage.decode(body, feedID: feedID, feedURL: URL(string: "\(Files.origin)/api/v1/feeds/\(feedID)")!)
                items += RichFeedMapper.items(from: page, source: source, fetchedAt: Files.now)
                identities.merge(RichFeedMapper.identities(from: page, source: source)) { first, _ in first }
            }
            #expect(items.count == objects.count, "\(name)")
            try await store.insert(items, identities: identities)
            let rows = try await store.rows()
            let stored = try await store.writer.read { db in try Item.fetchAll(db) }
            func row(_ index: Int) -> String? { stored.first { $0.remoteID == items[index].remoteID && $0.sourceID == items[index].sourceID }?.mergeKey }
            // Representations that share an identity, directly or through
            // a chain, are one row; two distinct posts that share a URL,
            // text and time are two.
            #expect(rows.count == (name == "distinct-posts-one-url" ? 2 : 1), "\(name)")
            for pair in entry["pairs"] as? [[String: Any]] ?? [] {
                let left = try #require(pair["left"] as? Int), right = try #require(pair["right"] as? Int)
                let shares = try #require(pair["sharesIdentity"] as? Bool)
                let sameRow = row(left) != nil && row(left) == row(right)
                if shares { #expect(sameRow, "\(name) \(left)-\(right)") }
                if name == "distinct-posts-one-url" { #expect(!sameRow, "\(name) \(left)-\(right)") }
            }
        }
    }

    @Test func the304SendsExactlyTheRecordedRequestAndKeepsTheCursor() async throws {
        let recorded = try Files.object("rich-feed-not-modified.json")
        let requestHeaders = try #require((recorded["request"] as? [String: Any])?["headers"] as? [String: String])
        let response = try #require(recorded["response"] as? [String: Any])
        let responseHeaders = try #require(response["headers"] as? [String: String])
        let status = try #require(response["status"] as? Int)
        #expect(status == 304)
        let pageHeaders = try Files.headers("page")
        let page = try Files.data("rich-feed-page-1.json")
        let http = FakeHTTPClient { request in
            guard let tag = request.value(forHTTPHeaderField: "If-None-Match") else { return .init(headers: pageHeaders, body: page) }
            return tag == requestHeaders["If-None-Match"] ? .init(status: status, headers: responseHeaders) : .init(status: 500)
        }
        let source = Files.source(.post)
        let connector = try Files.connector(http)
        let first = try await connector.fetch(Files.request(source), from: source)
        let validators = try #require(first.newer.flatMap(SammyFeedConnector.Validators.init(cursor:)))
        #expect(validators.etag == pageHeaders["ETag"])
        #expect(validators.accept == SammyNegotiation.rich)
        #expect(validators.format == .rich)

        let again = try await connector.fetch(Files.request(source, cursor: first.newer, stored: Set(first.items.map(\.remoteID))), from: source)
        #expect(again.items.isEmpty)
        #expect(again.newer == first.newer)
        #expect(http.requests.count == 2)
        let sent = try #require(http.requests.last)
        for (name, value) in requestHeaders {
            #expect(sent.value(forHTTPHeaderField: name) == value, "\(name)")
        }
    }

    @Test func a304OfAnotherRepresentationIsRefused() async throws {
        let source = Files.source(.post)
        let cases: [(SammyPage.Format, String, String)] = [
            (.rich, SammyNegotiation.rich, "W/\"2783f7f47fdabd661f4b857f03499625bca8290b\""),
            (.article, SammyNegotiation.rich, "W/\"rich-v1-7529b36ea90cc14d99fec8007028d114b137ba8e\""),
        ]
        for (format, accept, answered) in cases {
            let http = FakeHTTPClient { _ in .init(status: 304, headers: ["ETag": answered]) }
            let cursor = SammyFeedConnector.Validators(etag: "W/\"rich-v1-0\"", accept: accept, format: format).cursor
            await #expect(throws: ConnectorError.badResponse("a 304 for another representation")) {
                try await Files.connector(http).fetch(Files.request(source, cursor: cursor), from: source)
            }
        }
        // A validator from another Accept is not sent, so a 304 then
        // answers nothing that was asked.
        let http = FakeHTTPClient { _ in .init(status: 304, headers: ["ETag": "W/\"rich-v1-0\""]) }
        let older = SammyFeedConnector.Validators(etag: "W/\"rich-v1-0\"", accept: SammyNegotiation.either, format: .rich).cursor
        await #expect(throws: ConnectorError.self) { try await Files.connector(http).fetch(Files.request(source, cursor: older), from: source) }
        #expect(http.requests.first?.value(forHTTPHeaderField: "If-None-Match") == nil)
    }

    @Test func aRichETagIsKeptOnlyWithItsPrefix() async throws {
        let page = try Files.data("rich-feed-page-1.json")
        var headers = try Files.headers("page")
        headers["ETag"] = "W/\"2783f7f47fdabd661f4b857f03499625bca8290b\""
        let source = Files.source(.post)
        let fetched = try await Files.connector(Files.answering(page, headers: headers)).fetch(Files.request(source), from: source)
        let validators = try #require(fetched.newer.flatMap(SammyFeedConnector.Validators.init(cursor:)))
        #expect(validators.etag == nil)
        #expect(validators.format == .rich)
    }

    /// A catch-up saved as rich while the feed was unclassified sends the
    /// same Accept as an article feed; once the feed is listed as articles
    /// it starts from the top page rather than resume a rich link.
    @Test func aCatchUpInAFormatTheFeedNoLongerHoldsStartsFromTheTop() async throws {
        let source = Files.source(.article)
        let saved = SammyFeedConnector.Validators(etag: nil, resume: Files.secondPageURL, accept: SammyNegotiation.either, format: .rich)
        let article = try Files.data("feed-page-2.json", in: "Fixtures/SammyContract")
        let http = Files.answering(article, headers: ["Content-Type": "application/feed+json; charset=utf-8"])
        _ = try? await Files.connector(http).fetch(Files.request(source, cursor: saved.cursor), from: source)
        #expect(!http.requests.isEmpty)
        #expect(!http.requests.contains { $0.url?.absoluteString == Files.secondPageURL })
    }

    /// An older page link saved before the feed's classification changed
    /// may be refused, or served in the other format: that ends history
    /// instead of failing every older refresh on the same link.
    @Test func anOlderPageOfTheOtherRepresentationEndsHistory() async throws {
        let source = Files.source(.post)
        let older = Files.request(source, .older, cursor: Cursor(rawValue: Files.secondPageURL))
        let refused = try Files.answering(Files.data("rich-feed-page-expired.json"), headers: ["Content-Type": "application/json"], status: 406)
        let first = try await Files.connector(refused).fetch(older, from: source)
        #expect(first.items.isEmpty && first.older == nil)
        let article = try Files.answering(Files.data("feed-page-2.json", in: "Fixtures/SammyContract"), headers: ["Content-Type": "application/feed+json; charset=utf-8"])
        let second = try await Files.connector(article).fetch(older, from: source)
        #expect(second.items.isEmpty && second.older == nil)
    }

    @Test func anExpiredCursorEndsHistory() async throws {
        let headers = try Files.headers("page")
        let expired = try Files.data("rich-feed-page-expired.json")
        let source = Files.source(.post)
        let http = Files.answering(expired, headers: headers)
        let page = try await Files.connector(http).fetch(Files.request(source, .older, cursor: Cursor(rawValue: Files.secondPageURL)), from: source)
        #expect(page.items.isEmpty)
        #expect(page.older == nil)

        // Through the refresher, the source has reached its oldest.
        let store = try InfluxStore.inMemory()
        try await store.save(sources: [source])
        let refresher = Refresher(store: store)
        let connector = try Files.connector(try Files.pages())
        #expect(try await refresher.refresh(source, with: connector, now: Files.now) == .fetched(newItems: 2))
        let ending = try Files.connector(http)
        #expect(try await refresher.refresh(source, with: ending, direction: .older, now: Files.now) == .fetched(newItems: 0))
        #expect(try await store.fetchState(sourceID: source.id)?.reachedOldest == true)
        #expect(try await refresher.refresh(source, with: ending, direction: .older, now: Files.now) == .reachedOldest)
    }

