    // MARK: Refusals

    @Test func everyRecordedRefusalIsItsConnectorErrorAndStoresNothing() async throws {
        let refusals = try Files.object("rich-feed-refusals.json")
        let expected: [String: ConnectorError] = [
            "unauthorized": .unauthorized,
            "forbiddenScope": .unauthorized,
            "notFound": .notFound,
            "notAcceptableRich": .unsupported,
            "notAcceptableArticle": .unsupported,
            "notAcceptableList": .unsupported,
            "invalidCursor": .badResponse("HTTP 400"),
            "rateLimited": .rateLimited(retryAfter: nil),
            "sourceUnavailable": .badResponse("HTTP 502"),
            "notConfigured": .badResponse("HTTP 503"),
        ]
        #expect(Set(refusals.keys) == Set(expected.keys))
        for (name, error) in expected {
            let refusal = try #require(refusals[name] as? [String: Any])
            let status = try #require(refusal["status"] as? Int)
            let body = try JSONSerialization.data(withJSONObject: try #require(refusal["body"]))
            let http = FakeHTTPClient { _ in .init(status: status, headers: ["Content-Type": "application/json"], body: body) }
            let source = Files.source(.post)
            let store = try InfluxStore.inMemory()
            try await store.save(sources: [source])
            let outcome = try await Refresher(store: store).refresh(source, with: Files.connector(http), now: Files.now)
            #expect(outcome == .failed(error), "\(name)")
            #expect(try await store.rows().isEmpty, "\(name)")
            let state = try await store.fetchState(sourceID: source.id)
            #expect(state?.newerCursor == nil && state?.problem != nil, "\(name)")
            // The list is refused the same way.
            await #expect(throws: error, "\(name)") { try await Files.connector(http).availableSources() }
        }
    }

    @Test func aPageOfAnotherFormatFeedOrPathIsRefusedWhole() async throws {
        let headers = try Files.headers("page")
        let source = Files.source(.post)
        let changes: [(String, (inout [String: Any]) -> Void)] = [
            ("format", { $0["format"] = "sammy.rich-feed-list" }),
            ("version", { $0["version"] = 2 }),
            ("no version", { $0["version"] = nil }),
            ("feed", { $0["feed"] = ["id": "0193a1b2-0000-7000-8000-00000000f004", "title": "x", "feedUrl": "x"] }),
            ("origin", { $0["nextUrl"] = "https://other.example/api/v1/feeds/\(RichFixtures.richFeedID)?before=x" }),
            ("path", { $0["nextUrl"] = "\(RichFixtures.origin)/api/v1/feeds/0193a1b2-0000-7000-8000-00000000f004?before=x" }),
            ("credentials", { $0["nextUrl"] = "https://user:secret@example.com/api/v1/feeds/\(RichFixtures.richFeedID)?before=x" }),
            ("no items", { $0["items"] = nil }),
        ]
        for (name, change) in changes {
            let page = try Files.page("rich-feed-page-1.json", change)
            let store = try InfluxStore.inMemory()
            try await store.save(sources: [source])
            let outcome = try await Refresher(store: store).refresh(source, with: Files.connector(Files.answering(page, headers: headers)), now: Files.now)
            guard case .failed(.badResponse) = outcome else {
                Issue.record("\(name): \(outcome)")
                continue
            }
            #expect(try await store.rows().isEmpty, "\(name)")
        }
    }

    @Test func aPostThatBreaksARuleIsDroppedAlone() async throws {
        let headers = try Files.headers("page")
        let source = Files.source(.post)
        let items = try Files.pageOneItems()
        let changes: [(String, (inout [String: Any]) -> Void)] = [
            ("upper-case id", { $0["id"] = "urn:uuid:6562EF86-3D74-89A3-BE05-37A629CCD00C" }),
            ("id not a UUID URN", { $0["id"] = "https://www.example.com/author/posts/3" }),
            ("upper-case canonical ID", { $0["canonicalId"] = "urn:uuid:0193A1B2-0000-7000-8000-000000000003" }),
            ("canonical ID not a URN", { $0["canonicalId"] = "urn:example:3" }),
            ("an article", { $0["classification"] = ["kind": "article", "retentionDays": NSNull()] }),
            ("empty text", { $0["text"] = "" }),
            ("no author name", { $0["author"] = ["name": ""] }),
            ("http", { $0["url"] = "http://www.example.com/author/posts/3" }),
            ("credentials", { $0["url"] = "https://user:secret@www.example.com/author/posts/3" }),
            ("whitespace", { $0["url"] = "https://www.example.com/author/posts/3 x" }),
            ("no time", { $0["publishedAt"] = nil }),
            ("a date only", { $0["publishedAt"] = "2026-11-02" }),
            ("more links than the contract allows", {
                $0["links"] = (0...RichFeedPage.maxLinks).map { ["url": "https://www.example.com/l/\($0)"] }
            }),
            // Media breaks the post the same way.
            ("null media", { $0["media"] = NSNull() }),
            ("a null alt text", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "alt": NSNull()]] }),
            ("a null preview on an image", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "preview": NSNull()]] }),
            ("a null duration", { $0["media"] = [["id": "m", "kind": "video", "width": 10, "height": 10, "durationMs": NSNull()]] }),
            ("more media than the contract allows", {
                $0["media"] = (0...RichFeedPage.maxMedia).map { ["id": "m\($0)", "kind": "image", "width": 10, "height": 10] }
            }),
            ("media present but empty", { $0["media"] = [] }),
            ("a repeated media ID", {
                $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10], ["id": "m", "kind": "gif", "width": 10, "height": 10]]
            }),
            ("a media ID with a slash", { $0["media"] = [["id": "a/b", "kind": "image", "width": 10, "height": 10]] }),
            ("an over-long media ID", { $0["media"] = [["id": String(repeating: "a", count: 129), "kind": "image", "width": 10, "height": 10]] }),
            ("no width", { $0["media"] = [["id": "m", "kind": "image", "height": 10]] }),
            ("a width as text", { $0["media"] = [["id": "m", "kind": "image", "width": "10", "height": 10]] }),
            ("a zero height", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 0]] }),
            ("a side too long", { $0["media"] = [["id": "m", "kind": "image", "width": RichFeedPage.maxMediaSide + 1, "height": 10]] }),
            ("empty alt text", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "alt": ""]] }),
            ("over-long alt text", {
                $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "alt": String(repeating: "é", count: 1501)]]
            }),
            ("a duration on an image", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "durationMs": 5]] }),
            ("a preview on an image", { $0["media"] = [["id": "m", "kind": "image", "width": 10, "height": 10, "preview": false]] }),
            ("a zero duration", { $0["media"] = [["id": "m", "kind": "video", "width": 10, "height": 10, "durationMs": 0]] }),
            ("a duration over a day", {
                $0["media"] = [["id": "m", "kind": "video", "width": 10, "height": 10, "durationMs": RichFeedPage.maxDurationMs + 1]]
            }),
        ]
        for (name, change) in changes {
            var broken = items[1]
            change(&broken)
            let page = try Files.page("rich-feed-page-1.json") { $0["items"] = [items[0], broken] }
            let fetched = try await Files.connector(Files.answering(page, headers: headers)).fetch(Files.request(source), from: source)
            #expect(fetched.items.map(\.remoteID) == ["urn:uuid:70ad2d4e-b17f-8d6d-84e0-14a6d944d82b"], "\(name)")
        }
        // What the post carries beyond the rules is not read: odd
        // capabilities and extensions don't drop it.
        var odd = items[1]
        odd["capabilities"] = 5
        odd["extensions"] = "x"
        odd["somethingNew"] = ["a": 1]
        let page = try Files.page("rich-feed-page-1.json") { $0["items"] = [odd, "not a post"] }
        let fetched = try await Files.connector(Files.answering(page, headers: headers)).fetch(Files.request(source), from: source)
        #expect(fetched.items.map(\.remoteID) == ["urn:uuid:6562ef86-3d74-89a3-be05-37a629ccd00c"])
    }

    @Test func anAuthorsPictureThatIsntAMediaIDIsLeftOutAndThePostStays() async throws {
        let headers = try Files.headers("page")
        let source = Files.source(.post)
        let items = try Files.pageOneItems()
        let malformed: [Any] = [
            "https://www.example.com/a.jpg", ["url": "https://www.example.com/a.jpg"], ["id": "a/b"], ["id": ""],
            ["id": String(repeating: "a", count: 129)], ["id": 5], NSNull(), [["id": "a"]],
        ]
        for avatar in malformed {
            var post = items[1]
            post["author"] = ["name": "Example Author", "avatar": avatar]
            let page = try Files.page("rich-feed-page-1.json") { $0["items"] = [post] }
            let fetched = try await Files.connector(Files.answering(page, headers: headers)).fetch(Files.request(source), from: source)
            #expect(fetched.items.count == 1, "\(avatar)")
            #expect(fetched.items.first?.authorAvatar == nil, "\(avatar)")
        }
        // A media ID, with fields this build doesn't know beside it, is a picture.
        var post = items[1]
        post["author"] = ["name": "Example Author", "avatar": ["id": "av_1-A", "width": 400]]
        let page = try Files.page("rich-feed-page-1.json") { $0["items"] = [post] }
        let fetched = try await Files.connector(Files.answering(page, headers: headers)).fetch(Files.request(source), from: source)
        let reference = try #require(fetched.items.first?.authorAvatar.flatMap(SammyMediaReference.init))
        #expect(reference.mediaID == "av_1-A" && reference.feedID == RichFixtures.richFeedID)
    }

    @Test func whatTheSourceHoldsMustBeWhatTheServerSends() async throws {
        let rich = try Files.data("rich-feed-page-1.json")
        let article = try Files.data("feed-page-1.json", in: "Fixtures/SammyContract")
        let richHeaders = try Files.headers("page")
        // Listed as posts, answered as an article: no article fallback.
        await #expect(throws: ConnectorError.badResponse("a rich feed answered as an article feed")) {
            try await Files.connector(Files.answering(article, headers: Files.articlePageHeaders))
                .fetch(Files.request(Files.source(.post)), from: Files.source(.post))
        }
        // Listed as articles, answered with posts.
        await #expect(throws: ConnectorError.badResponse("an article feed answered with posts")) {
            try await Files.connector(Files.answering(rich, headers: richHeaders))
                .fetch(Files.request(Files.source(.article)), from: Files.source(.article))
        }
        // A body that names a format is never an article.
        await #expect(throws: ConnectorError.badResponse("not a JSON Feed")) {
            try await Files.connector(Files.answering(rich, headers: Files.articlePageHeaders))
                .fetch(Files.request(Files.source(nil)), from: Files.source(nil))
        }
    }

    @Test func aCatchUpThatMixesFormatsIsRefused() async throws {
        let richHeaders = try Files.headers("page")
        let first = try Files.data("rich-feed-page-1.json")
        let article = try Files.data("feed-page-2.json", in: "Fixtures/SammyContract")
        let http = FakeHTTPClient { request in
            request.url?.query() == nil ? .init(headers: richHeaders, body: first) : .init(headers: RichFixtures.articlePageHeaders, body: article)
        }
        let source = Files.source(nil)
        let cursor = SammyFeedConnector.Validators(etag: nil, accept: SammyNegotiation.either, format: .rich).cursor
        await #expect(throws: ConnectorError.badResponse("a catch-up that mixes formats")) {
            try await Files.connector(http).fetch(Files.request(source, cursor: cursor, stored: ["urn:uuid:00000000-0000-0000-0000-000000000000"]), from: source)
        }
        #expect(http.requests.count == 2)
    }
